// Obtener el texto del agente menu
let text = '';

// Buscar en las ubicaciones comunes
if ($('Agente menu').first().json.output) {
  text = ($('Agente menu').first().json.output)
} else {
  return { json: { output: "Error: No se encontró texto del agente" } };
}

// Validar que hay texto
if (!text || text.trim() === '') {
  return { json: { output: "Error: Respuesta vacía del agente" } };
}

// Límite WhatsApp: 1600 chars, usamos 1500 para safety
const maxLength = 1500;

// Si es corto, enviar directo
if (text.length <= maxLength) {
  return { json: { output: text } };
}

// Si es largo, dividir inteligentemente
const chunks = [];
let currentPos = 0;

while (currentPos < text.length) {
  let endPos = Math.min(currentPos + maxLength, text.length);

  // Si no es el último chunk, buscar un punto de corte natural
  if (endPos < text.length) {
    // Buscar el último salto de línea, punto, o espacio antes del límite
    const lastNewline = text.lastIndexOf('\n', endPos);
    const lastPeriod = text.lastIndexOf('.', endPos);
    const lastSpace = text.lastIndexOf(' ', endPos);

    // Usar el mejor punto de corte disponible
    const bestCut = Math.max(lastNewline, lastPeriod, lastSpace);
    if (bestCut > currentPos + 100) { // Solo si no es muy cerca del inicio
      endPos = bestCut + 1;
    }
  }

  const chunk = text.substring(currentPos, endPos).trim();
  if (chunk) {
    // Añadir numeración para orden claro
    const partNumber = chunks.length + 1;
    const totalEstimated = Math.ceil(text.length / maxLength);

    if (totalEstimated > 1) {
      chunks.push(`📋 Parte ${partNumber}/${totalEstimated}:\n\n${chunk}`);
    } else {
      chunks.push(chunk);
    }
  }

  currentPos = endPos;
}

// Para múltiples chunks, devolver solo el primero
// (n8n maneja múltiples outputs secuencialmente)
if (chunks.length > 1) {
  // Retornar array de objetos para que n8n procese en orden
  return chunks.map(chunk => ({ json: { output: chunk } }));
} else {
  return { json: { output: chunks[0] || text } };
}

// Obtener el mensaje del nodo UserMessage
const input = $('UserMessage').first().json.mensaje || "";

// Expresión regular:
// - Busca 'ORDER_' sin importar mayúsculas/minúsculas
// - Después del _ exige uno o más dígitos
const regex = /order_(\d+)/i;

// Buscar coincidencia
const match = input.match(regex);

// Retornamos:
// - orderCode: la coincidencia completa (ORDER_3)
// - orderNumber: solo el número (3), convertido a número
return [
  {
    json: {
      orderCode: match ? match[0].toUpperCase() : null,
      orderNumber: match ? Number(match[1]) : null,
    }
  }
];

// items = sucursales (varios items)
const fromNumber =  $('GlobalFields').first().json.fromNumber;

// Ajusta estos nombres según tu salida real de Supabase:
const getZone = (s) => s.zone || s.zona || 'Sucursales';
const getTitle = (s) => s.name || s.title || s.nombre || 'Sucursal';
const getDesc = (s) => s.description || s.descripcion || '';
const getId = (s) => s.id; // id único de la sucursal (ideal: uuid/int)

const grouped = new Map();

for (const it of items) {
  const s = it.json;

  const zone = getZone(s);
  if (!grouped.has(zone)) grouped.set(zone, []);

  grouped.get(zone).push({
    // IMPORTANTE: este "id" es el que WhatsApp te devuelve cuando el usuario elige
    // Hazlo único y fácil de parsear luego:
    id: `sucursal:${getId(s)}`,
    title: getTitle(s),
    description: getDesc(s),
  });
}

// Convertir a sections[]
const sections = Array.from(grouped.entries()).map(([title, rows]) => ({
  title,
  rows,
}));

// (Opcional) límites de WhatsApp: conviene recortar
// Ejemplo: máximo 10 secciones y 10 filas por sección
const MAX_SECTIONS = 10;
const MAX_ROWS_PER_SECTION = 10;

const sectionsLimited = sections.slice(0, MAX_SECTIONS).map(sec => ({
  ...sec,
  rows: sec.rows.slice(0, MAX_ROWS_PER_SECTION),
}));

return [
  {
    json: {
      body: {
        messaging_product: "whatsapp",
        recipient_type: "individual",
        to: fromNumber,
        type: "interactive",
        interactive: {
          type: "list",
          header: { type: "text", text: "Selecciona una Sucursal" },
          body: { text: "Por favor, elige la sucursal más cercana para continuar con tu pedido." },
          footer: { text: "Opciones disponibles" },
          action: {
            button: "Ver Sucursales",
            sections: sectionsLimited,
          },
        },
      },
    },
  },
];
